    # First, let's find all nodes that can reach a 2 without passing through a 1 (except themselves if they are 1)
    can_reach_2 = [False] * n
    # Process in reverse topological order would be ideal, but let's use BFS from all 2s
    # Actually, let's do BFS from all 2s in reverse graph, stopping at 1s
